  <div class="trail-element trail-horizontal">
    <svg viewBox="0 0 24 24" class="trail-icon">
      <circle cx="12" cy="12" r="10" fill="currentColor"/>
    </svg>
  </div>
</div>

<!-- Variant 2: Vertical fall -->
<div class="trail-stage">
  <div class="trail-element trail-vertical"></div>
</div>

<!-- Variant 3: Diagonal bounce -->
<div class="trail-stage">
  <div class="trail-element trail-diagonal"></div>
</div>
```

