  </div>
  <div class="has-card">
    <img src="https://picsum.photos/seed/b/300/200" alt="gallery item" />
    <p>Forest</p>
  </div>
  <div class="has-card">
    <img src="https://picsum.photos/seed/c/300/200" alt="gallery item" />
    <p>Ocean</p>
  </div>
</div>

<!-- Pricing card cascade -->
