:root {
  --focus-color: #6366f1;
  --focus-width: 2px;
}

/* Base: never remove outline */
[class*="focus-aura"] {
  outline: var(--focus-width) solid transparent;
  outline-offset: 0px;
  transition: outline-offset 0.3s ease, outline-color 0.3s ease;
  border-radius: 6px;
  padding: 10px 20px;
  cursor: pointer;
}

/* 1. Expanding Aura */
.focus-aura-expand:focus-visible {
  outline-color: var(--focus-color);
  animation: aura-expand 0.35s ease-out forwards;
}

@keyframes aura-expand {
  from { outline-offset: -6px; outline-color: rgba(99, 102, 241, 0.2); }
  to   { outline-offset:  6px; outline-color: rgba(99, 102, 241, 1);   }
}

/* 2. Pulse Ring */
.focus-aura-pulse:focus-visible {
  outline-color: var(--focus-color);
  outline-offset: 4px;
  animation: aura-pulse 1.6s ease-in-out 0.3s infinite;
}

@keyframes aura-pulse {
  0%, 100% { outline-offset: 4px;  outline-color: rgba(99, 102, 241, 1);   }
  50%       { outline-offset: 12px; outline-color: rgba(99, 102, 241, 0.1); }
}

/* 3. Inset-to-Outset Sweep */
.focus-aura-sweep:focus-visible {
  animation: aura-sweep 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}

@keyframes aura-sweep {
  0%   { outline-offset: -8px; outline-color: rgba(99, 102, 241, 0.6); }
  60%  { outline-offset:  8px; outline-color: rgba(99, 102, 241, 1);   }
  100% { outline-offset:  5px; outline-color: rgba(99, 102, 241, 0.9); }
}

/* 4. Neon Glow Aura */
.focus-aura-neon:focus-visible {
  outline-color: var(--focus-color);
  animation: aura-neon 0.3s ease-out forwards;
}

@keyframes aura-neon {
  from {
    outline-offset: 0px;
    box-shadow: 0 0 0 0 rgba(99, 102, 241, 0);
  }
  to {
    outline-offset: 4px;
    box-shadow:
      0 0 0 4px rgba(99, 102, 241, 0.15),
      0 0 12px 2px rgba(99, 102, 241, 0.3);
  }
}

/* Always preserve visibility for reduced-motion users */
@media (prefers-reduced-motion: reduce) {
  [class*="focus-aura"]:focus-visible {
    animation: none;
    outline-color: var(--focus-color);
    outline-offset: 4px;
  }
}
```

