.dof-scene:has(input[value="mid"]:checked) .plane-mid  { backdrop-filter: blur(0px); }
.dof-scene:has(input[value="mid"]:checked) .plane-near { backdrop-filter: blur(5px); }

/* Shift focus to far */
.dof-scene:has(input[value="far"]:checked) .plane-far  { backdrop-filter: blur(0px); }
.dof-scene:has(input[value="far"]:checked) .plane-mid  { backdrop-filter: blur(4px); }
.dof-scene:has(input[value="far"]:checked) .plane-near { backdrop-filter: blur(9px); }

