  width: 20px; /* in focus: sharp, small */
  filter: blur(0);
}

.dof-scene:has(input[value="near"]:checked) .plane-far .bokeh-dot {
  width: 50px; /* out of focus: big bokeh disc */
  filter: blur(6px);
}

@media (prefers-reduced-motion: reduce) {
  .plane { transition: none; }
  .bokeh-dot { transition: none; }
