@property --hue {
  syntax: '<angle>';
  inherits: false;
  initial-value: 0deg;
}

.hue-card {
  width: 100px;
  height: 120px;
  border-radius: 12px;
}

/* OKLCH: perceptually uniform, @property enables true hue interpolation */
.oklch-card {
  background: oklch(65% 0.22 var(--hue));
  animation: hue-spin 4s linear infinite;
  animation-delay: calc(var(--card-i) * -0.8s);
}

/* HSL: without @property registration, this also animates --hue
   but the luminance is perceptually uneven through the cycle */
.hsl-card {
  background: hsl(calc(var(--hue) / 1deg), 70%, 55%);
  animation: hue-spin 4s linear infinite;
  animation-delay: calc(var(--card-i) * -0.8s);
}

@keyframes hue-spin {
  from { --hue: 0deg;   }
  to   { --hue: 360deg; }
}

@media (prefers-reduced-motion: reduce) {
  .hue-card { animation: none; }
}
```

