.scroll-contain { overscroll-behavior: contain; }
.scroll-none    { overscroll-behavior: none;    }

.scroll-box {
  height: 180px;
  overflow-y: scroll;
  border: 2px solid #334155;
  border-radius: 8px;
  padding: 8px;
}

/* Propagation arrow animates when auto-box is focused */
.chain-arrow {
  opacity: 0;
  transform: translateY(-8px);
  transition: opacity 0.2s;
}

.scroll-auto:focus-within ~ .chain-arrow {
  animation: propagate 1.4s ease-in-out infinite;
}

@keyframes propagate {
  0%   { opacity: 0; transform: translateY(-8px); }
  30%  { opacity: 1; }
  100% { opacity: 0; transform: translateY(12px); }
}

/* Block flash fires when contain-box is focused */
.scroll-contain:focus-within ~ .block-flash {
  animation: blocked 0.5s ease-out forwards;
}

@keyframes blocked {
  0%   { opacity: 0; transform: scale(0.8); }
  50%  { opacity: 1; transform: scale(1.1); color: #f43f5e; }
  100% { opacity: 1; transform: scale(1);   color: #f43f5e; }
}

