## CSS Snippet

```css
@property --mask-r1 {
  syntax: '<percentage>';
  inherits: false;
  initial-value: 0%;
}

@property --mask-r2 {
  syntax: '<percentage>';
  inherits: false;
  initial-value: 0%;
}

/* Donut iris: only the ring between two circles is revealed */
.mask-intersect {
  -webkit-mask-image:
    radial-gradient(circle, transparent var(--mask-r1), black calc(var(--mask-r1) + 1%)),
    radial-gradient(circle, black var(--mask-r2), transparent calc(var(--mask-r2) + 1%));
  -webkit-mask-composite: source-in;
  mask-image:
    radial-gradient(circle, transparent var(--mask-r1), black calc(var(--mask-r1) + 1%)),
    radial-gradient(circle, black var(--mask-r2), transparent calc(var(--mask-r2) + 1%));
  mask-composite: intersect;
  animation: iris-open 1.8s ease-out forwards;
}

@keyframes iris-open {
  0%   { --mask-r1: 0%;  --mask-r2: 0%;  }
  40%  { --mask-r1: 0%;  --mask-r2: 45%; }
  100% { --mask-r1: 30%; --mask-r2: 80%; }
}

@media (prefers-reduced-motion: reduce) {
  [class*='mask-'] {
    animation: none;
    -webkit-mask-image: none;
    mask-image: none;
  }
}
```

