```css
/* One keyframe to rule them all */
@keyframes parametric-motion {
  from {
    transform: translate(0, 0) rotate(0deg) scale(1);
    opacity: 1;
  }
  to {
    transform:
      translate(var(--travel-x, 0px), var(--travel-y, -60px))
      rotate(var(--rotation, 0deg))
      scale(var(--end-scale, 1));
    opacity: var(--end-opacity, 1);
  }
}

.motion-atom {
  /* Apply the shared keyframe — all config comes from custom props */
  animation:
    parametric-motion
    var(--duration, 0.8s)
    var(--easing, ease)
    var(--delay, 0s)
    infinite
    alternate;

