<div class="layer-demo">
  <h2>Layer Cascade — Which Animation Wins?</h2>

  <div class="layer-stack">
    <code>@layer base, theme, override</code>
    <p class="note">Higher position in the declaration = lower priority</p>
  </div>

  <!-- The contested element -->
  <div class="demo-box layer-box">
    <span>Watch me change</span>
  </div>

  <!-- Layer toggles (pure CSS) -->
  <div class="layer-controls">
    <label><input type="checkbox" class="toggle-base" checked> Enable base layer (slow blue pulse)</label>
    <label><input type="checkbox" class="toggle-theme" checked> Enable theme layer (fast pink bounce)</label>
    <label><input type="checkbox" class="toggle-override" checked> Enable override layer (green spin)</label>
    <label><input type="checkbox" class="toggle-unlayered"> Enable unlayered rule (always wins)</label>
  </div>

  <!-- Unlayered contestant -->
  <div class="demo-box demo-box--unlayered layer-box"></div>
  <p class="note">This box uses an unlayered rule. It always beats all layers.</p>
</div>
