```css
@keyframes lissajous {
  to { --t: 1turn; }
}

@property --t {
  syntax: '<angle>';
  initial-value: 0turn;
  inherits: false;
}

.lissajous-loader span {
  position: absolute;
  animation: lissajous 2s linear infinite;
  animation-delay: calc(var(--i) * -0.15s);
  transform: translate(
    calc(sin(var(--t)) * 60px),
    calc(cos(calc(var(--t) * 2)) * 40px)
