  <p>Some content in a folded corner card.</p>
</div>

<!-- Top-right fold -->
<div class="ease-fold-card ease-fold-card--top-right">
  <h3>Important</h3>
  <p>Corner fold variant.</p>
</div>

<!-- Auto-animated on load -->
