  <div class="ease-mosaic__tile" style="--i: 0">01</div>
  <div class="ease-mosaic__tile" style="--i: 1">02</div>
  <div class="ease-mosaic__tile" style="--i: 2">03</div>
  <div class="ease-mosaic__tile" style="--i: 3">04</div>
  <div class="ease-mosaic__tile" style="--i: 4">05</div>
  <div class="ease-mosaic__tile" style="--i: 5">06</div>
  <div class="ease-mosaic__tile" style="--i: 6">07</div>
  <div class="ease-mosaic__tile" style="--i: 7">08</div>
  <div class="ease-mosaic__tile" style="--i: 8">09</div>
</div>
```

---

## CSS Snippet

```css
.ease-mosaic {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  padding: 1rem;
}

/* Default directional vars */
.ease-mosaic__tile {
  --tx: 0px;
  --ty: 0px;
  aspect-ratio: 1;
  background: #6366f1;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-weight: 700;
  animation: tile-arrive 0.5s cubic-bezier(0.22, 1, 0.36, 1) both;
  animation-delay: calc(var(--i) * 0.06s);
}

/* Four-directional origin via nth-child */
.ease-mosaic__tile:nth-child(4n + 1) { --tx: -120%; --ty: 0px; }
.ease-mosaic__tile:nth-child(4n + 2) { --tx: 0px;   --ty: -120%; }
.ease-mosaic__tile:nth-child(4n + 3) { --tx: 120%;  --ty: 0px; }
.ease-mosaic__tile:nth-child(4n + 4) { --tx: 0px;   --ty: 120%; }

@keyframes tile-arrive {
  from {
    transform: translate(var(--tx), var(--ty));
    opacity: 0;
  }
  to {
    transform: translate(0, 0);
    opacity: 1;
  }
}

/* Speed variants */
.ease-mosaic--fast .ease-mosaic__tile  { animation-duration: 0.28s; }
.ease-mosaic--slow .ease-mosaic__tile  { animation-duration: 0.8s; }

@media (prefers-reduced-motion: reduce) {
  .ease-mosaic__tile { animation: none; opacity: 1; }
}
```

