.ease-domino-row {
  display: flex;
  align-items: flex-end;
  gap: 10px;
  padding: 2rem;
  perspective: 600px;
}

.ease-domino {
  width: 32px;
  height: 96px;
  background: linear-gradient(160deg, #6366f1, #8b5cf6);
  border-radius: 4px;
  transform-origin: center bottom;
  animation: none;
