.ease-domino-row:hover .ease-domino {
  animation: domino-fall 0.45s cubic-bezier(0.4, 0, 0.6, 1) both;
  animation-delay: calc(var(--i) * 0.1s);
}

@keyframes domino-fall {
  0%   { transform: rotateX(0deg); }
  100% { transform: rotateX(80deg); }
}

/* 3D variant */
.ease-domino-row--3d {
  perspective: 800px;
}

.ease-domino-row--3d .ease-domino {
  transform-style: preserve-3d;
}

.ease-domino-row--3d:hover .ease-domino {
  animation-name: domino-fall-3d;
}

@keyframes domino-fall-3d {
